const aliases: Record<string, string> = {
  "Microsoft Teams": "MS Teams",
};

const icons: Record<string, string> = {
  ...chipIcons,
  ...extraWorkAppIcons,
};

export function IntegrationIcon({ name, className = "size-4" }: { name: string; className?: string }) {
  const html = icons[name] ?? icons[aliases[name] ?? ""];
  if (!html) {
    const letter = name.replace(/[^A-Za-z0-9]/g, "").charAt(0).toUpperCase();
    return (
      <span
        aria-hidden="true"
        className={`flex ${className} shrink-0 items-center justify-center rounded-md bg-white/8 font-heading text-[11px] font-semibold text-white/80`}
      >
        {letter}
      </span>
    );
  }
  return (
    <span
      aria-hidden="true"
      className={`inline-flex ${className} shrink-0 items-center justify-center [&_svg]:size-full`}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
